## 3. Implement login, logout, and session validation

```python
# app/auth/routes.py
from flask import Blueprint, current_app, jsonify, request, session
from flask_login import (
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_wtf.csrf import generate_csrf
from sqlalchemy.exc import SQLAlchemyError

from ..extensions import login_manager
from ..models import User, db  # Adjust to your existing module locations.

auth = Blueprint("auth", __name__)


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@auth.get("/csrf-token")
def csrf_token():
    response = jsonify(csrf_token=generate_csrf())
    response.headers["Cache-Control"] = "no-store"
    return response


@auth.post("/login")
def login():
    data = request.get_json(silent=True)

    if not isinstance(data, dict):
        return jsonify(error="Expected a JSON object"), 400

    username = data.get("username")
    password = data.get("password")

    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify(error="Username and password are required"), 400

    username = username.strip()

    # Example input limits: align these with your registration policy.
    if not 1 <= len(username) <= 80 or not 1 <= len(password) <= 1024:
        return jsonify(error="Invalid input lengths"), 400

    # Do not strip or otherwise modify the password.
    try:
        user = db.session.execute(
            db.select(User).where(User.username == username)
        ).scalar_one_or_none()

        if user is None or not user.check_password(password):
            return jsonify(error="Invalid username or password"), 401

        if not user.is_active:
            return jsonify(error="Invalid username or password"), 401

        session.clear()
        login_user(user, remember=False)
        session.permanent = True

        return jsonify(message="Login successful"), 200

    except SQLAlchemyError:
        db.session.rollback()
        current_app.logger.exception("Database error during login")
        return jsonify(error="Unable to log in right now"), 500


@auth.post("/logout")
@login_required
def logout():
    logout_user()
    session.clear()
    return jsonify(message="Logged out"), 200


@auth.get("/me")
@login_required
def me():
    return jsonify(
        id=current_user.id,
        username=current_user.username,
    ), 200
```

**How this works:** `login_user()` establishes the session. On subsequent requests, Flask-Login calls `load_user()` to retrieve the real database user. Unlike your earlier placeholder loader, it does not authenticate arbitrary IDs by constructing a user object.

## 4. Call it from your frontend

For a same-origin frontend:

```javascript
async function login(username, password) {
  const tokenResponse = await fetch("/csrf-token", {
    credentials: "same-origin"
  });
  const { csrf_token } = await tokenResponse.json();

  const response = await fetch("/login", {
    method: "POST",
    credentials: "same-origin",
    headers: {
      "Content-Type": "application/json",
      "X-CSRFToken": csrf_token
    },
    body: JSON.stringify({ username, password })
  });

  const result = await response.json();

  if (!response.ok) {
    throw new Error(result.error);
  }

  return result;
}
```

Fetch a **new CSRF token after login**, because the login route clears the previous session. Include it when submitting logout or other state-changing requests.

